#include "cpartydialog.hpp"
#include <algorithm>
namespace mxh::ui{void cPartyDialog::AddMember(PartyMember m){if(m.id==0||m.name.empty()||std::any_of(m_members.begin(),m_members.end(),[&](const auto&x){return x.id==m.id;}))return;if(m_members.empty())m.leader=true;else m.leader=false;m_members.push_back(std::move(m));}bool cPartyDialog::RemoveMember(std::uint32_t id){auto it=std::find_if(m_members.begin(),m_members.end(),[&](const auto&x){return x.id==id;});if(it==m_members.end()||it->id==m_self||it->leader)return false;m_members.erase(it);return true;}bool cPartyDialog::TransferLeader(std::uint32_t id){auto it=std::find_if(m_members.begin(),m_members.end(),[&](const auto&x){return x.id==id;});if(it==m_members.end()||m_self==0||std::none_of(m_members.begin(),m_members.end(),[&](const auto&x){return x.id==m_self&&x.leader;}))return false;for(auto&m:m_members)m.leader=(m.id==id);return true;}bool cPartyDialog::Invite(std::string_view n){return !n.empty()&&m_invite&&m_invite(n);}const PartyMember* cPartyDialog::Leader()const noexcept{auto it=std::find_if(m_members.begin(),m_members.end(),[](const auto&m){return m.leader;});return it==m_members.end()?nullptr:&*it;}}
